/**
 * The app-facing API, served at `<function URL>/<sessionID>`:
 *
 * - `PUT`: start a session, or update its push token (tokens can rotate).
 *   Body: `{ pushToken, apnsEnvironment, stopID, lineID, stopName?, endsAt }`.
 * - `PATCH`: rename the stop. Body: `{ stopName }`.
 * - `DELETE`: stop refreshing; the app ends the activity itself.
 *
 * There are no accounts. The session UUID, generated by the app, is the only
 * capability needed to change a session.
 */
import type { ApnsEnvironment } from "./apns";
import { servesStop } from "./catalog";
import { truncatedStopName } from "./snapshot";
import type { NewSession, SessionStore } from "./store";
import { type TickTask, tickTime } from "./tick";

/** Matches `BusArrivalAttributes.sessionDuration` in the app. */
export const SESSION_SECONDS = 15 * 60;
/** A personal app: more than this at once means something is wrong. */
export const MAX_ACTIVE_SESSIONS = 20;

const SESSION_ID_PATTERN =
  /^[0-9A-F]{8}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{4}-[0-9A-F]{12}$/;
const PUSH_TOKEN_PATTERN = /^[0-9a-f]{64,512}$/;
const LINE_ID_PATTERN = /^[0-9A-Z]{1,8}$/;

export interface SessionsDeps {
  sessions: SessionStore;
  schedule(task: TickTask, runAt: number): Promise<void>;
  /** Seconds since 1970. */
  now(): number;
}

export interface HttpResult {
  status: number;
  body?: Record<string, unknown>;
}

const fail = (status: number, error: string): HttpResult => ({ status, body: { error } });

export async function handleSessionsRequest(
  deps: SessionsDeps,
  method: string,
  path: string,
  body: unknown,
): Promise<HttpResult> {
  const sessionID = path.replace(/^\/+|\/+$/g, "").toUpperCase();
  if (!SESSION_ID_PATTERN.test(sessionID)) return fail(404, "Unknown session");

  switch (method) {
    case "PUT":
      return register(deps, sessionID, body);
    case "PATCH": {
      const stopName = (body as { stopName?: unknown } | undefined)?.stopName;
      if (stopName !== null && typeof stopName !== "string") {
        return fail(400, "stopName must be a string or null");
      }
      const updated = await deps.sessions.update(sessionID, {
        stopName: truncatedStopName(stopName) ?? null,
      });
      return updated ? { status: 204 } : fail(404, "Unknown session");
    }
    case "DELETE":
      await deps.sessions.delete(sessionID);
      return { status: 204 };
    default:
      return fail(405, "Method not allowed");
  }
}

async function register(
  deps: SessionsDeps,
  sessionID: string,
  body: unknown,
): Promise<HttpResult> {
  const now = deps.now();
  const parsed = parseRegistration(sessionID, body, now);
  if ("error" in parsed) return fail(400, parsed.error);
  const session = parsed.session;

  const mutable = {
    pushToken: session.pushToken,
    apnsEnvironment: session.apnsEnvironment,
    stopName: session.stopName,
  };
  if (await deps.sessions.update(sessionID, mutable)) return { status: 200 };

  if ((await deps.sessions.countActive(now)) >= MAX_ACTIVE_SESSIONS) {
    return fail(429, "Too many active sessions");
  }
  if (!(await deps.sessions.create(session))) {
    // Created concurrently by a retried request.
    await deps.sessions.update(sessionID, mutable);
    return { status: 200 };
  }

  try {
    await deps.schedule({ sessionID, tick: 1 }, tickTime(session, 1, now));
  } catch {
    await deps.sessions.delete(sessionID);
    return fail(503, "Could not schedule refreshes");
  }
  return { status: 201 };
}

export function parseRegistration(
  sessionID: string,
  body: unknown,
  now: number,
): { session: NewSession } | { error: string } {
  if (typeof body !== "object" || body === null) return { error: "Expected a JSON body" };
  const { pushToken, apnsEnvironment, stopID, lineID, stopName, endsAt } =
    body as Record<string, unknown>;

  if (typeof pushToken !== "string" || !PUSH_TOKEN_PATTERN.test(pushToken.toLowerCase())) {
    return { error: "pushToken must be a hex APNs token" };
  }
  if (apnsEnvironment !== "sandbox" && apnsEnvironment !== "production") {
    return { error: "apnsEnvironment must be sandbox or production" };
  }
  if (typeof stopID !== "number" || !Number.isInteger(stopID)) {
    return { error: "stopID must be an integer" };
  }
  if (typeof lineID !== "string" || !LINE_ID_PATTERN.test(lineID) || !servesStop(stopID, lineID)) {
    return { error: "lineID does not serve stopID" };
  }
  if (stopName !== undefined && stopName !== null && typeof stopName !== "string") {
    return { error: "stopName must be a string" };
  }
  if (typeof endsAt !== "number" || !Number.isFinite(endsAt)) {
    return { error: "endsAt must be seconds since 1970" };
  }

  // The server enforces the session length, whatever the app asks for.
  const deadline = Math.min(endsAt, now + SESSION_SECONDS);
  if (deadline <= now) return { error: "The session has already ended" };

  return {
    session: {
      sessionID,
      pushToken: pushToken.toLowerCase(),
      apnsEnvironment: apnsEnvironment as ApnsEnvironment,
      stopID,
      lineID,
      stopName: truncatedStopName(stopName) ?? null,
      createdAt: now,
      endsAt: deadline,
    },
  };
}
